const tombGiantSheet=new Image();tombGiantSheet.assetSrc='assets/tomb-giant-v2.png';
function beginTombGiant(e){let angle=Math.atan2(p.y-e.y,p.x-e.x)+Math.PI*2/9;e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'tombGiantBurial',bespoke:true,windup:2,origin:{x:e.x,y:e.y},fired:false,tombs:Array.from({length:3},(_,i)=>{let a=angle+i*Math.PI*2/3,x=e.x+Math.cos(a)*140,y=e.y+Math.sin(a)*140;return {x,y,angle:a,valid:passable(x,y,28)&&lineClear(e,{x,y})};})};}
function tombGiantSheltered(a,point){let dx=point.x-a.origin.x,dy=point.y-a.origin.y,r=Math.hypot(dx,dy);if(r<168-1e-8||r>420+1e-8)return false;let angle=Math.atan2(dy,dx);return a.tombs.some(t=>t.valid&&Math.abs(Math.atan2(Math.sin(angle-t.angle),Math.cos(angle-t.angle)))<=Math.asin(.2)+1e-10);}
const tombGiantAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r10e4')return tombGiantAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='tombGiantBurial'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=300&&clear){beginTombGiant(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,52*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,28)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&e.elapsed>=2){a.fired=true;e.struck=true;if(dist(a.origin,p)<=420&&!tombGiantSheltered(a,p)&&lineClear(a.origin,p))hurt(105);playSound('impact',e.x,e.y);}
 if(e.elapsed>=a.windup+1){e.attack=null;e.state='idle';e.t=2.8;}
};
const tombGiantDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r10e4'||!tombGiantSheet.complete||!tombGiantSheet.naturalWidth||!tombGiantSheet.naturalHeight)return tombGiantDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='tombGiantBurial')f={row:2,col:e.elapsed<1.2?0:e.elapsed<a.windup?1:e.elapsed<a.windup+.25?2:3};let q=project(e.x,e.y),sw=tombGiantSheet.naturalWidth/4,sh=tombGiantSheet.naturalHeight/3,w=330,h=w*sh/sw,anchor=[[.82,.82,.82,.82],[.8,.82,.82,.82],[.81,.81,.81,.81]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,tombGiantSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(tombGiantSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const tombGiantSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r10e4'?250:tombGiantSizeBase(e);
function drawTombShelter(a,t){let half=Math.asin(.2),points=[];for(let i=0;i<=8;i++){let angle=t.angle-half+half*2*i/8;points.push(project(a.origin.x+Math.cos(angle)*420,a.origin.y+Math.sin(angle)*420));}for(let i=8;i>=0;i--){let angle=t.angle-half+half*2*i/8;points.push(project(a.origin.x+Math.cos(angle)*168,a.origin.y+Math.sin(angle)*168));}ctx.beginPath();points.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));ctx.closePath();ctx.fillStyle='rgba(110,220,174,.18)';ctx.fill();ctx.strokeStyle='#83d8ae';ctx.lineWidth=1;ctx.stroke();}
const tombGiantGroundBase=drawGroundEffects;drawGroundEffects=()=>{tombGiantGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r10e4'):enemies)){let a=e.attack;if(e.species!=='r10e4'||e.hp<=0||a?.pattern!=='tombGiantBurial'||e.elapsed>2.4||!visibleAt(e.x,e.y))continue;groundRing(a.origin.x,a.origin.y,420,a.fired?'#e5c5ff':'#a18bb4',2);if(a.fired)groundRing(a.origin.x,a.origin.y,420,'#e5c5ff',5);ctx.save();for(let t of a.tombs){if(!t.valid)continue;if(!a.fired)drawTombShelter(a,t);let q=project(t.x,t.y),height=42*Math.min(1,e.elapsed/.6);ctx.fillStyle='#696777';ctx.strokeStyle='#b8b4ca';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x-19,q.y);ctx.lineTo(q.x-19,q.y-height+8);ctx.lineTo(q.x,q.y-height);ctx.lineTo(q.x+19,q.y-height+8);ctx.lineTo(q.x+19,q.y);ctx.closePath();ctx.fill();ctx.stroke();}ctx.restore();}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r10e4',animateEnemy,drawRegionEnemy);
